counts = {"http": 0, "token": 0, "unauthorized": 0, "rate_limited": 0, "server_error": 0, "network_error": 0}


def log(message):
    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S.%f")[:-3]
    with open(LOG_PATH, "a", encoding="utf-8") as handle:
        handle.write(f"{stamp} {message}\n")


def save(name, payload):
    with open(os.path.join(RAW_DIR, name), "w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=1)


def send(method, path, authed):
    headers = {}
    if authed:
        headers["Authorization"] = "Bearer " + state["token"]
    request = urllib.request.Request(BASE + path, method=method, headers=headers)
    counts["http"] += 1
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            status, raw_headers, body = response.status, response.headers, response.read()
    except urllib.error.HTTPError as error:
        status, raw_headers, body = error.code, error.headers, error.read()
    return status, {key.lower(): value for key, value in raw_headers.items()}, body


