    """Seconds the service asked us to wait, from Retry-After or a JSON field; None if unreadable."""
    value = headers.get("retry-after")
    if value is not None:
        try:
            return float(value)
        except ValueError:
            return max(0.0, parsedate_to_datetime(value).timestamp() - time.time())
    try:
        data = json.loads(body)
    except ValueError:
        return None
    if isinstance(data, dict):
        for key, item in data.items():
            if ("retry" in key.lower() or "wait" in key.lower()) and isinstance(item, (int, float)):
                return float(item)
    return None


