        if authed and state["token"] is None:
            state["token"] = request_json("POST", "/token", authed=False)["token"]
            just_refreshed = True
            counts["token"] += 1
            log(f"token obtained (total {counts['token']})")
        try:
            status, headers, body = send(method, path, authed)
        except OSError as error:
