    raise RuntimeError(f"gave up on {method} {path} after 100 attempts")


def fetch_pages():
    pages = []
    path = "/orders?page=1"
    expected = 1
    total = None
    while path is not None:
        data = request_json("GET", path)
        if data["page"] != expected:
            raise RuntimeError(f"requested page {expected}, service returned page {data['page']}")
        if total is None:
            total = data["total_pages"]
        if data["total_pages"] != total:
            raise RuntimeError(f"total_pages changed from {total} to {data['total_pages']}")
        save(f"orders_page_{expected:03d}.json", data)
        log(f"orders page {expected}/{total}: {len(data['items'])} items, next={data['next']!r}")
