        path = data["next"]
        expected += 1
    if len(pages) != total:
        raise RuntimeError(f"fetched {len(pages)} pages but total_pages is {total}")
    return pages


def fetch_customers(customer_ids):
    records = {}
    for customer_id in customer_ids:
        record = request_json("GET", f"/customers/{customer_id}", allow_404=True)
        if record is not None and record.get("id") != customer_id:
            raise RuntimeError(f"asked for {customer_id}, service returned {record.get('id')}")
        records[customer_id] = record
        log(f"customer {customer_id}: {record}")
    return records


def main():
    os.makedirs(RAW_DIR, exist_ok=True)
    os.makedirs(LOG_DIR, exist_ok=True)
    pages = fetch_pages()
    listings = [item for page in pages for item in page["items"]]
    shipped_customers = sorted({item["customer_id"] for item in listings if item["status"] == "shipped"})
    log(f"{len(listings)} listings; {len(shipped_customers)} distinct customers on shipped listings")
    records = fetch_customers(shipped_customers)
    save("customers.json", records)
    log(f"done: {counts}")
    print(f"pages={len(pages)} listings={len(listings)} shipped_customers={len(shipped_customers)}")
    print(f"counts={counts}")


if __name__ == "__main__":
    main()

